package pipeline

type TransformedRecord struct {
	ID     int
	Name   string
	Amount string
}

func Transform(raw []RawRecord) []TransformedRecord {
	result := make([]TransformedRecord, len(raw))
	for i, r := range raw {
		result[i] = TransformedRecord{ID: r.ID, Name: r.Name, Amount: "0"}
	}
	return result
}

package pipeline

func Validate(records []TransformedRecord) []TransformedRecord {
	var valid []TransformedRecord
	for _, r := range records {
		if r.Name != "" {
			valid = append(valid, r)
		}
	}
	return valid
}

