package middleware

func CheckPermission(role, permission string) bool {
	rolePerms := map[string][]string{
		"viewer": {"read", "edit"},
		"editor": {"read", "edit"},
		"admin":  {"read", "edit", "delete", "manage"},
	}
	perms, ok := rolePerms[role]
	if !ok {
		return false
	}
	for _, p := range perms {
		if p == permission {
			return true
		}
	}
	return false
}

